CREATE OR REPLACE FUNCTION public.check_form_section_graph()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE old_version TEXT; new_version TEXT;
BEGIN
  IF TG_TABLE_NAME = 'FormVersion' THEN
    IF TG_OP <> 'INSERT' THEN old_version:=OLD.id; END IF;
    IF TG_OP <> 'DELETE' THEN new_version:=NEW.id; END IF;
  ELSIF TG_TABLE_NAME = 'QuestionOption' THEN
    IF TG_OP <> 'INSERT' THEN SELECT "formVersionId" INTO old_version FROM "Question" WHERE id=OLD."questionId"; END IF;
    IF TG_OP <> 'DELETE' THEN SELECT "formVersionId" INTO new_version FROM "Question" WHERE id=NEW."questionId"; END IF;
  ELSE
    IF TG_OP <> 'INSERT' THEN old_version:=OLD."formVersionId"; END IF;
    IF TG_OP <> 'DELETE' THEN new_version:=NEW."formVersionId"; END IF;
  END IF;
  IF old_version IS NOT NULL THEN PERFORM assert_form_section_graph(old_version); END IF;
  IF new_version IS NOT NULL AND new_version IS DISTINCT FROM old_version THEN PERFORM assert_form_section_graph(new_version); END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_custom_choice_parent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE form_id text;
BEGIN
  IF NEW.type IS NOT DISTINCT FROM OLD.type THEN RETURN NEW; END IF;
  IF current_setting('transaction_isolation') NOT IN ('read committed','read uncommitted') THEN
    RAISE EXCEPTION 'Question type mutations require READ COMMITTED' USING ERRCODE='0A000';
  END IF;
  SELECT "formId" INTO form_id FROM "FormVersion" WHERE id=NEW."formVersionId";
  PERFORM id FROM "Form" WHERE id=form_id FOR UPDATE;
  IF NEW.type NOT IN ('객관식 답변','체크박스','드롭다운')
    AND EXISTS (SELECT 1 FROM "QuestionOption" WHERE "questionId"=NEW.id AND "isCustomValue"=true) THEN
    RAISE EXCEPTION 'Remove custom choices before changing question type' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_published_question()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP <> 'INSERT' AND EXISTS (SELECT 1 FROM "FormVersion" WHERE id = OLD."formVersionId" AND status = 'published') THEN
    RAISE EXCEPTION 'Published questions are immutable' USING ERRCODE = '23514';
  END IF;
  IF TG_OP <> 'DELETE' AND EXISTS (SELECT 1 FROM "FormVersion" WHERE id = NEW."formVersionId" AND status = 'published') THEN
    RAISE EXCEPTION 'Published questions are immutable' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

