CREATE OR REPLACE FUNCTION public.guard_custom_choice_option()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE form_id text; parent_type text;
BEGIN
  IF NEW."isCustomValue" IS NOT TRUE THEN RETURN NEW; END IF;
  IF current_setting('transaction_isolation') NOT IN ('read committed','read uncommitted') THEN
    RAISE EXCEPTION 'Custom choice mutations require READ COMMITTED' USING ERRCODE='0A000';
  END IF;
  SELECT v."formId" INTO form_id FROM "Question" q JOIN "FormVersion" v ON v.id=q."formVersionId" WHERE q.id=NEW."questionId";
  PERFORM id FROM "Form" WHERE id=form_id FOR UPDATE;
  SELECT type INTO parent_type FROM "Question" WHERE id=NEW."questionId";
  IF parent_type IS NULL OR parent_type NOT IN ('객관식 답변','체크박스','드롭다운') THEN
    RAISE EXCEPTION 'Custom choices require a supported choice question' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_option_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE form_id text; question_key text;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF OLD."stableKey" IS NOT NULL AND (NEW."stableKey" IS DISTINCT FROM OLD."stableKey" OR NEW.value IS DISTINCT FROM OLD.value OR NEW."questionId"<>OLD."questionId") THEN
   RAISE EXCEPTION 'Option identity/value is immutable' USING ERRCODE='23514';
  END IF;
  IF OLD."stableKey" IS NULL AND NEW."stableKey" IS NOT NULL AND (NEW."stableKey"<>OLD.id OR NEW.value<>OLD.value OR NEW."questionId"<>OLD."questionId") THEN
   RAISE EXCEPTION 'Legacy identity must retain its row identity and value' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW."stableKey" IS NOT NULL THEN
  SELECT v."formId",q."stableKey" INTO form_id,question_key FROM "Question" q JOIN "FormVersion" v ON v.id=q."formVersionId" WHERE q.id=NEW."questionId";
  -- Serializes same-form identity checks, including direct database writers.
  PERFORM id FROM "Form" WHERE id=form_id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM "QuestionOption" o JOIN "Question" q ON q.id=o."questionId" JOIN "FormVersion" v ON v.id=q."formVersionId"
   WHERE v."formId"=form_id AND (o."stableKey"=NEW."stableKey" OR (o."stableKey" IS NULL AND o.id=NEW."stableKey"))
    AND (q."stableKey"<>question_key OR o.value<>NEW.value)) THEN
   RAISE EXCEPTION 'Option identity belongs to another question or value' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_published_option()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE question_id TEXT;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    IF EXISTS (SELECT 1 FROM "Question" q JOIN "FormVersion" v ON v.id=q."formVersionId" WHERE q.id=OLD."questionId" AND v.status='published') THEN
      RAISE EXCEPTION 'Published options are immutable' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    IF EXISTS (SELECT 1 FROM "Question" q JOIN "FormVersion" v ON v.id=q."formVersionId" WHERE q.id=NEW."questionId" AND v.status='published') THEN
      RAISE EXCEPTION 'Published options are immutable' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$
